import java.util.Scanner;public class Main {    public static void main(String[] args) {        ArbolInventario inventario = new ArbolInventario();        Scanner scanner = new Scanner(System.in);        int opcion;        do {            System.out.println("\n=== SISTEMA DE INVENTARIO TREE-STOCK ===");            System.out.println("1. Registrar Producto");            System.out.println("2. Mostrar Inventario");            System.out.println("3. Buscar Producto");            System.out.println("0. Salir");            System.out.print("Seleccione una opción: ");            opcion = scanner.nextInt();            switch (opcion) {                case 1:                    System.out.print("Ingrese ID del producto: ");                    int id = scanner.nextInt();                    scanner.nextLine();                    System.out.print("Ingrese nombre del producto: ");                    String nombre = scanner.nextLine();                    inventario.insertar(id, nombre);                    System.out.println("Producto registrado correctamente.");                    break;                case 2:                    System.out.println("\nInventario ordenado:");                    inventario.mostrarInventario();                    break;                case 3:                    System.out.print("Ingrese ID a buscar: ");                    int idBuscar = scanner.nextInt();                    Producto encontrado = inventario.buscar(idBuscar);                    if (encontrado != null) {                        System.out.println("Producto encontrado: " + encontrado.nombre);                    } else {                        System.out.println("Producto no existe.");                    }                    break;                case 0:                    System.out.println("Saliendo del sistema...");                    break;                default:                    System.out.println("Opción inválida.");            }        } while (opcion != 0);        scanner.close();    }}